  23 
  24 export function SectionAccordionItem({
  25     section,
  26     chapterIndex,
  27     sectionIndex,
  28     isProjectBuildMode,
  29     isSelected,
  30     isActive,
  31     onActivate,
  32     toggleSectionSelection,
  33 }: SectionAccordionItemProps) {
  34     const { project } = useBuilderStore();
  35 
  36     const { generateSectionMutation } = useAiActions();
  37 
  38     const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: section.id });
  39 
  40     const style: React.CSSProperties = {
  41         transform: CSS.Transform.toString(transform),
  42         transition,
  43         zIndex: isDragging ? 2 : 0,
  44         position: 'relative',
  45     };
  46 
  47     if (!section) return null;
  48 
  49     const isGenerating = generateSectionMutation?.isPending && generateSectionMutation.variables === section.id;
  50 
  51     const getContextNames = (proj: Project | null, sec: Section): string[] => {
  52         if (!proj || !sec.context) return [];
  53 
  54         const sectionNames = Object.keys(sec.context.sections || {}).map(id => proj?.getSection(id)?.title || 'Untitled Section');
  55         const fileNames = Object.keys(sec.context.externalContext || {}).map(id => proj?.externalContext?.find(f => f.id === id)?.fileName || 'Untitled File');
  56 
  57         return [...sectionNames, ...fileNames];
  58     };
  59 
  60     const contextNames = getContextNames(project, section);
  61     const totalContext = contextNames.length;
  62 
  63     const handleActivate = () => onActivate(section.id);
  64 
