   8 export function useContextSelector(itemKey: string) {
   9     const { t } = useLocalization();
  10     const { project, updateProject } = useBuilderStore();
  11 
  12     const section = useMemo(() => project?.getSection(itemKey), [project, itemKey]);
  13 
  14     const currentSelection = useMemo(() => {
  15         return section?.context || { sections: {}, externalContext: {} };
  16     }, [section?.context]);
  17 
  18     const reportSections = useMemo(() => {
  19         if (!project?.sections) return [];
  20         return project.sections
  21             .filter(section => section.id !== itemKey)
  22             .map(section => ({ id: section.id, title: section.title }));
  23     }, [project?.sections, itemKey]);
  24     
  25     const sectionsContent = useMemo(() => {
  26         if (!project?.sections) return {};
  27         return project.sections.reduce<Record<string, string>>((acc, currentSection) => {
  28             acc[currentSection.id] = currentSection.content || '';
  29             return acc;
  30         }, {});
  31     }, [project?.sections]);
  32 
  33 
  34     const handleContextChange = useCallback((
  35         sectionId: string,
  36         type: 'sections' | 'externalContext',
  37         subKey: string,
  38         value: ExternalContextType | false
  39     ) => {
  40         updateProject(currentProject => currentProject.updateSection(sectionId, (sec) => {
  41             const existingContext = sec.context || { sections: {}, externalContext: {} };
  42             const newContext = { ...existingContext };
  43             const newDict = { ...(newContext[type] || {}) };
  44 
  45             if (value === false) {
  46                 delete newDict[subKey];
  47             } else {
  48                 newDict[subKey] = value;
  49             }
  50 
  51             newContext[type] = newDict;
  52             return sec.withProps({ context: newContext });
  53         }));
  54     }, [updateProject]);
  55 
  56     return {
  57         t,
  58         reportSections,
  59         handleContextChange,
  60         currentSelection,
  61         sections: sectionsContent,
  62         externalContext: project?.externalContext || [],
  63     };
  64 }
