  11     const response = await fetch(`${baseUrl}/api/projects/${id}`, {
  12       headers: {
  13         'Cookie': `__session=${token}`
  14       },
  15       next: { revalidate: 0 } // Bypass cache for builder to ensure fresh data
  16     });
  17     
  18     if (response.ok) {
  19       const result = await response.json();
  20       return result as ProjectProperties;
  21     }
  22   } catch (error) {
  23     console.error('Failed to fetch initial project on server:', error);
  24   }
  25   return null;
