{"file_path":"src/app/builder/content/page.tsx","overwrite":true,"initial_content":"import { Suspense } from 'react';
import { cookies } from 'next/headers';

import { BuilderPageSkeleton } from '../loading';
import BuilderContentWorkspace from '@/components/report-mode/builder-content/BuilderContentWorkspace';
import { ProjectProperties } from '@/lib/types';

async function getInitialProject(id: string, token: string | undefined) {
  if (!id || !token) return null;

  try {
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:9002';
    const response = await fetch(`${baseUrl}/api/projects/${id}`, {
      headers: {
        Cookie: `__session=${token}`,
      },
      next: { revalidate: 0 },
    });

    if (response.ok) {
      const result = await response.json();
      return result as ProjectProperties;
    }
  } catch (error) {
    console.error('Failed to fetch initial project on server:', error);
  }

  return null;
}

export default async function BuilderContentPage(props: { searchParams: Promise<{ id?: string }> }) {
  const searchParams = await props.searchParams;
  const projectId = searchParams.id;
  const cookieStore = await cookies();
  const sessionToken = cookieStore.get('__session')?.value;

  const initialProject = projectId ? await getInitialProject(projectId, sessionToken) : null;

  return (
    <Suspense fallback={<BuilderPageSkeleton />}>
      <BuilderContentWorkspace initialProject={initialProject} />
    </Suspense>
  );
}
"}

