            <Badge variant="outline" className="gap-1.5 rounded-full px-3 py-1 text-xs font-medium">
              <BadgeCheck className="h-3.5 w-3.5" />
              {locale === 'ar' ? 'RTL Ready' : 'Professional Layout'}
            </Badge>
