        </div>

        {isMobile ? (
          <div className="flex flex-1 flex-col gap-4">
            <Tabs value={mobilePanel} onValueChange={(value) => setMobilePanel(value as 'left' | 'center' | 'right')}>
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="left">Navigator</TabsTrigger>
                <TabsTrigger value="center">Document</TabsTrigger>
                <TabsTrigger value="right">Inspector</TabsTrigger>
