                  onActiveSectionChange={setActiveSectionId}
                />
              </div>
              <div className={cn(mobilePanel !== 'center' && 'hidden')}>
                <BuilderContentCenterPanel activePanelKey={documentMode} />
              </div>
              <div className={cn(mobilePanel !== 'right' && 'hidden')}>
