   7 async function getInitialProject(id: string, token: string | undefined) {
   8   if (!id || !token) return null;
   9 
  10   try {
  11     const baseUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:9002';
  12     const response = await fetch(`${baseUrl}/api/projects/${id}`, {
  13       headers: {
  14         Cookie: `__session=${token}`,
  15       },
  16       next: { revalidate: 0 },
  17     });
  18 
  19     if (response.ok) {
  20       const result = await response.json();
  21       return result as ProjectProperties;
  22     }
  23   } catch (error) {
  24     console.error('Failed to fetch initial project on server:', error);
  25   }
  26 
  27   return null;
  28 }
  29 
  30 export default async function BuilderContentPage(props: { searchParams: Promise<{ id?: string }> }) {
  31   const searchParams = await props.searchParams;
  32   const projectId = searchParams.id;
  33   const cookieStore = await cookies();
  34   const sessionToken = cookieStore.get('__session')?.value;
  35 
  36   const initialProject = projectId ? await getInitialProject(projectId, sessionToken) : null;
  37 
  38   return (
  39     <Suspense fallback={<BuilderPageSkeleton />}>
  40       <BuilderContentWorkspace initialProject={initialProject} />
  41     </Suspense>
  42   );
  43 }
